"use strict";(self.webpackChunkgf_site=self.webpackChunkgf_site||[]).push([["1924"],{55226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"0.2.x(Latest)","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"quickSidebar":[{"type":"link","href":"/quick/overview","label":"Project Overview","docId":"quick/overview","unlisted":false},{"type":"link","href":"/quick/environment","label":"Environment Setup","docId":"quick/environment","unlisted":false},{"type":"link","href":"/quick/installation","label":"Quick Installation","docId":"quick/installation","unlisted":false},{"type":"link","href":"/quick/have-a-try","label":"Development Experience","docId":"quick/have-a-try","unlisted":false}],"docsSidebar":[{"type":"category","label":"Design Principles","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai-native","label":"AI-Native Design","docId":"docs/concepts/ai-native","unlisted":false},{"type":"link","href":"/docs/modular-design","label":"Modular Design","docId":"docs/concepts/modular-design","unlisted":false},{"type":"link","href":"/docs/spec-driven-development","label":"AI Spec-Driven Development","docId":"docs/concepts/spec-driven-development","unlisted":false},{"type":"link","href":"/docs/ai-engineering-quality","label":"AI Engineering Quality Assurance","docId":"docs/concepts/ai-engineering-quality","unlisted":false}],"href":"/docs/concepts"},{"type":"category","label":"Component Design","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/core-host","label":"Core Host Service","docId":"docs/components/core-host","unlisted":false},{"type":"link","href":"/docs/admin-workspace","label":"Built-in Admin Workspace","docId":"docs/components/admin-workspace","unlisted":false},{"type":"category","label":"Dual-Mode Plugin System","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/source-plugins","label":"Source Plugins","docId":"docs/components/plugin-system/source-plugins","unlisted":false},{"type":"link","href":"/docs/wasm-plugins","label":"Dynamic Plugins (WASM)","docId":"docs/components/plugin-system/wasm-plugins","unlisted":false},{"type":"link","href":"/docs/plugin-management","label":"Plugin Management","docId":"docs/components/plugin-system/plugin-management","unlisted":false},{"type":"link","href":"/docs/capability-boundary","label":"Host and Plugin Capability Boundaries","docId":"docs/components/plugin-system/capability-boundary","unlisted":false}],"href":"/docs/plugin-system"},{"type":"link","href":"/docs/distributed-architecture","label":"Native Distributed Architecture","docId":"docs/components/distributed-architecture","unlisted":false},{"type":"link","href":"/docs/configuration","label":"Service Configuration","docId":"docs/components/configuration","unlisted":false},{"type":"link","href":"/docs/routing","label":"Routing Management","docId":"docs/components/routing","unlisted":false},{"type":"link","href":"/docs/permission","label":"Permission Management","docId":"docs/components/permission","unlisted":false},{"type":"link","href":"/docs/static-assets","label":"Static Asset Management","docId":"docs/components/static-assets","unlisted":false},{"type":"link","href":"/docs/api-reference","label":"OpenAPI Reference","docId":"docs/components/api-reference","unlisted":false},{"type":"link","href":"/docs/multi-tenant","label":"Native Multi-Tenancy","docId":"docs/components/multi-tenant","unlisted":false},{"type":"link","href":"/docs/cron-tasks","label":"Scheduled Tasks","docId":"docs/components/cron-tasks","unlisted":false},{"type":"link","href":"/docs/i18n","label":"Framework-Level Internationalization","docId":"docs/components/i18n","unlisted":false}],"href":"/docs/components"},{"type":"category","label":"Development Tools","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/commands","label":"Development Commands","docId":"docs/tools/commands","unlisted":false},{"type":"link","href":"/docs/agent-skills","label":"Development Skills","docId":"docs/tools/agent-skills","unlisted":false}],"href":"/docs/tools"}],"communitySidebar":[{"type":"link","href":"/community","label":"Community","docId":"community/community","unlisted":false},{"type":"link","href":"/community/support","label":"Support Us","docId":"community/support","unlisted":false}]},"docs":{"community/community":{"id":"community/community","title":"Community","description":"Official LinaPro community channels \u2014 QQ groups, WeChat, Discord, and GitHub Issues \u2014 with guidance on which channel is best for real-time discussion, reproducible bugs, feature requests, documentation feedback, and plugin development questions.","sidebar":"communitySidebar"},"community/support":{"id":"community/support","title":"Support Us","description":"Practical ways to support the long-term maintenance of LinaPro, including filing reproducible issues, improving documentation, sharing production experience, joining community discussions, and donating through WeChat Pay or Alipay. Please include your GitHub or Gitee account name in the donation note so we can keep an accurate donation record.","sidebar":"communitySidebar"},"docs/components/admin-workspace":{"id":"docs/components/admin-workspace","title":"Built-in Admin Workspace","description":"A component-level guide to the LinaPro built-in admin workspace, lina-vben \u2014 how it serves as the standard frontend consumer of the core host service and plugin system, covering access control, system settings, job scheduling, multi-tenant management, plugin governance, developer center, and dynamic plugin pages, while maintaining consistency with backend API contracts, menu permissions, and I18N resources.","sidebar":"docsSidebar"},"docs/components/api-reference":{"id":"docs/components/api-reference","title":"OpenAPI Reference","description":"From a component design perspective, this page explains how LinaPro aggregates API documentation \u2014 the core host, source plugins, and WASM dynamic plugins are unified into a single OpenAPI document through g.Meta contracts, permission tags, API doc i18n resources, the in-workspace developer center debugging page, and third-party tool import.","sidebar":"docsSidebar"},"docs/components/components":{"id":"docs/components/components","title":"Component Design","description":"An overview of the LinaPro component design philosophy: separating a stable platform foundation from pluggable business extensions, replacing implicit coupling with explicit contracts, and delivering capabilities as self-contained, composable units. Authentication, RBAC, multi-tenancy, scheduling, i18n, cluster coordination, and API documentation are built into the host; business capabilities are delivered as independent plugins; the frontend and backend are decoupled through public API contracts.","sidebar":"docsSidebar"},"docs/components/configuration":{"id":"docs/components/configuration","title":"Service Configuration","description":"A component-level guide to LinaPro core host service configuration \u2014 how config.yaml drives HTTP server, logging, database, JWT authentication, sessions, monitoring, health probes, scheduling, internationalization, cluster coordination, file uploads, and plugin governance, with production deployment recommendations.","sidebar":"docsSidebar"},"docs/components/core-host":{"id":"docs/components/core-host","title":"Core Host Service","description":"A component-level guide to the LinaPro core host service lina-core \u2014 covering API contracts, governance services, runtime configuration, API documentation aggregation, scheduling, internationalization, multi-tenant foundation, plugin runtime, cluster coordination, and health probes, and how the host serves as a stable foundation for the workspace, source plugins, and WASM dynamic plugins.","sidebar":"docsSidebar"},"docs/components/cron-tasks":{"id":"docs/components/cron-tasks","title":"Scheduled Tasks","description":"A component-level guide to the LinaPro persistent scheduled task system \u2014 task types, cron expressions, task groups, execution logs, built-in tasks, source plugin and dynamic plugin task declarations, master_only and all_node execution scopes, singleton and parallel concurrency strategies, and cluster scheduling behavior.","sidebar":"docsSidebar"},"docs/components/distributed-architecture":{"id":"docs/components/distributed-architecture","title":"Native Distributed Architecture","description":"From a component design perspective, this page explains the native distributed architecture of LinaPro \u2014 how to switch between single-node and cluster mode, the Redis coordinator, leader election, node responsibilities, cache revision, distributed locks, key-value cache, scheduled task execution scope, and the horizontal scaling process \u2014 helping developers understand how business code can scale to multi-node deployment with zero modifications.","sidebar":"docsSidebar"},"docs/components/i18n":{"id":"docs/components/i18n","title":"Framework-Level Internationalization","description":"A component-level guide to the LinaPro I18N internationalization runtime \u2014 how host language packs, plugin language packs, dynamic plugin language resources, API documentation translations, runtime caching, locale configuration, and frontend language switching work together, and what resource boundaries teams must maintain when adding new languages.","sidebar":"docsSidebar"},"docs/components/multi-tenant":{"id":"docs/components/multi-tenant","title":"Native Multi-Tenancy","description":"A component-level guide to LinaPro multi-tenancy \u2014 how the host bizctx, TenantFilterService, tenant_id filtering interface, default platform tenant, official multi-tenant source plugin, tenant impersonation, plugin multi-tenant manifest fields, and the current Pool shared-database model work together.","sidebar":"docsSidebar"},"docs/components/permission":{"id":"docs/components/permission","title":"Permission Management","description":"This article covers the permission management strategy of the LinaPro core host service, including the issuance, parsing, and revocation of dual JWTs (Access Token and Refresh Token), lifecycle management of both token types, online session management via hot-state storage, the design of the RBAC role-permission model (three-tier relationship: role \u2192 menu \u2192 permission), token-scoped access context caching with revision-based invalidation, declarative API permission management via g.Meta struct tags and the Permission middleware enforcement flow, and menu permission management (menu types, role-menu associations, permission trees, and data scope control) \u2014 giving developers a complete understanding of the authentication and authorization system.","sidebar":"docsSidebar"},"docs/components/plugin-system/capability-boundary":{"id":"docs/components/plugin-system/capability-boundary","title":"Host and Plugin Capability Boundaries","description":"This page explains how LinaPro defines capability boundaries between the main framework and plugins. It covers the default admin workspace, host control-plane APIs, the unified plugin API namespace, public plugin asset hosting, source-plugin HTTP routes, and the division of responsibility between source plugins and dynamic plugins. It also describes how plugins access host capabilities through stable extension interfaces, and how plugin menus, permissions, public pages, and public_assets declarations are governed so developers can understand exactly how the host and plugins collaborate without leaking responsibilities into each other.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-management":{"id":"docs/components/plugin-system/plugin-management","title":"Plugin Management","description":"From a component design and operational flow perspective, this page explains LinaPro plugin management \u2014 plugin source configuration, the local plugin workspace, plugins.init, plugins.install, plugins.update, plugins.status, admin workspace installation and enablement, disablement and uninstallation, dynamic plugin upload, and runtime upgrade \u2014 covering the full chain from code acquisition to runtime activation.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-system":{"id":"docs/components/plugin-system/plugin-system","title":"Dual-Mode Plugin System","description":"A component-level guide to the LinaPro dual-mode plugin system \u2014 why source plugins and WASM dynamic plugins share the same governance pipeline, and how catalog, dependency, lifecycle, integration, plugin-runtime cache, pluginhost, pluginbridge, plugin.yaml, multi-tenant fields, lifecycle states, isolation mechanisms, and runtime upgrades together form an extensible plugin architecture.","sidebar":"docsSidebar"},"docs/components/plugin-system/source-plugins":{"id":"docs/components/plugin-system/source-plugins","title":"Source Plugins","description":"A component-level and developer-practice guide to LinaPro source plugins \u2014 use cases, directory structure, plugin.yaml manifest, installation SQL, API contracts, service layer implementation, pluginhost registration, database access, frontend pages, event hooks, runtime upgrades, and best practices for extending long-term business capabilities with native Go.","sidebar":"docsSidebar"},"docs/components/plugin-system/wasm-plugins":{"id":"docs/components/plugin-system/wasm-plugins","title":"Dynamic Plugins (WASM)","description":"An introduction to WebAssembly (WASM) fundamentals and advantages \u2014 cross-platform support, secure sandboxing, near-native performance, hot-loading, and multi-language ecosystem \u2014 followed by a practical guide to LinaPro WASM dynamic plugins covering use cases, sandbox model, pluginbridge protocol, exported functions, hostServices authorization, build process, runtime installation and enablement, explicit upgrades, and key differences from source plugins.","sidebar":"docsSidebar"},"docs/components/routing":{"id":"docs/components/routing","title":"Routing Management","description":"This article covers the routing management strategy of the LinaPro core host service, including API versioning (/api/v1 prefix conventions), the built-in middleware pipeline (unified response, CORS, request body limits, business context injection, JWT authentication, tenant resolution, permission enforcement), layered auth-route design, inline API attribute management via g.Meta struct tags, and the contrasting routing strategies between source plugins (free to register any path) and dynamic plugins (constrained to /x/{pluginID}/ prefix), helping developers understand the framework routing architecture and follow best practices.","sidebar":"docsSidebar"},"docs/components/static-assets":{"id":"docs/components/static-assets","title":"Static Asset Management","description":"This page explains LinaPro static asset management, including how the host service and plugins use Go Embed to compile static files into binaries, the Go Embed model, asset directory conventions, host static asset routing priority, Vue page asset handling for source plugins, and how dynamic plugins carry frontend assets through WASM custom sections, cache them in host memory, and serve them on demand.","sidebar":"docsSidebar"},"docs/concepts/ai-engineering-quality":{"id":"docs/concepts/ai-engineering-quality","title":"AI Engineering Quality Assurance","description":"A systematic look at the engineering management challenges that arise when AI is introduced into software development, and how LinaPro builds a complete AI engineering quality assurance system through the SDD spec-driven workflow, two layers of project specifications, interface abstraction and anti-leakage API contracts, and high-density test coverage where test code accounts for 39% of the total codebase.","sidebar":"docsSidebar"},"docs/concepts/ai-native":{"id":"docs/concepts/ai-native","title":"AI-Native Design","description":"A detailed look at LinaPro as an AI-native framework \u2014 what AI-native truly means, how it differs from AI-assisted development, how AI participates in every stage of the development lifecycle, the built-in AI skill system covering backend, frontend, testing, performance auditing, and version management, and why spec-driven development prevents architectural drift over time.","sidebar":"docsSidebar"},"docs/concepts/concepts":{"id":"docs/concepts/concepts","title":"Design Principles","description":"An introduction to the core design principles behind LinaPro, including AI-native design, modular architecture, AI spec-driven development, and AI engineering quality assurance, helping developers build the right mental model before going deeper into the framework.","sidebar":"docsSidebar"},"docs/concepts/modular-design":{"id":"docs/concepts/modular-design","title":"Modular Design","description":"An exploration of LinaPro modular design \u2014 how the leanness principle (keep the core minimal, extend through plugins), domain-bounded built-in capabilities, a first-class plugin system, stable extension interfaces, and real-world examples like cloud storage and LDAP/OIDC authentication let developers assemble systems from proven building blocks rather than building everything from scratch.","sidebar":"docsSidebar"},"docs/concepts/spec-driven-development":{"id":"docs/concepts/spec-driven-development","title":"AI Spec-Driven Development","description":"A detailed guide to LinaPro Specification-Driven Development (SDD) and the OpenSpec workflow \u2014 the five-stage development loop (explore, propose, implement, review, archive), the responsibilities of AI and humans at each stage, the OpenSpec directory structure and spec file formats, and how spec anchors and mandatory E2E tests prevent architectural drift.","sidebar":"docsSidebar"},"docs/tools/agent-skills":{"id":"docs/tools/agent-skills","title":"Development Skills","description":"This page introduces LinaPro\'s AI-focused skill system, including the optional externally installed OpenSpec CLI, goframe-v2, and find-skills tools or skills, plus project-bundled skills for frontend design, Git workflows, code review, E2E testing, performance auditing, OpenSpec implementation and archiving, and other workflows that load automatically in the project. It also notes that source plugin upgrade scenarios may depend on the lina-upgrade skill provided by the AI tool environment, helping developers understand what each skill does, how to install it, and how to invoke it.","sidebar":"docsSidebar"},"docs/tools/commands":{"id":"docs/tools/commands","title":"Development Commands","description":"This page describes the cross-platform development command set used by LinaPro, including linactl, the Makefile compatibility entry, the Windows make.cmd wrapper, local environment checks and setup, development server management, full builds, WASM plugin builds, Docker image builds, plugin workspace management, agent resource symlink management, test validation, i18n checks, database initialization, and release governance. It helps developers use the same project toolchain consistently on macOS, Linux, and Windows.","sidebar":"docsSidebar"},"docs/tools/tools":{"id":"docs/tools/tools","title":"Development Tools","description":"An overview of the developer tooling built into LinaPro \u2014 covering every make command with usage examples, and the full AI skills library for frontend design, code review, testing, performance auditing, and OpenSpec workflows.","sidebar":"docsSidebar"},"quick/environment":{"id":"quick/environment","title":"Environment Setup","description":"This guide explains every dependency required to run LinaPro from source, including Git, Go (1.25+), Node.js (20.19+), pnpm (10.0+), PostgreSQL 14+, the cross-platform linactl development command entry, and the recommended AI-native workflow tools and skills such as Claude Code, OpenSpec CLI, goframe-v2, and find-skills. It also provides installation guidance for macOS, Linux, and Windows so developers can prepare a local development environment before installing LinaPro.","sidebar":"quickSidebar"},"quick/have-a-try":{"id":"quick/have-a-try","title":"Development Experience","description":"This guide uses a complete article management CRUD source plugin example to demonstrate LinaPro\'s AI-native development workflow. It covers requirement exploration with the spec-driven workflow, OpenSpec proposal generation, AI-led code implementation, service startup and feature verification, feedback-driven fixes, and change archival, helping developers understand how LinaPro turns AI Coding tools into a full-cycle delivery process for real business features.","sidebar":"quickSidebar"},"quick/installation":{"id":"quick/installation","title":"Quick Installation","description":"This guide explains how to install and initialize the LinaPro framework in a few minutes. It covers cloning the source repository with Git, initializing official plugin submodules when needed, preparing the default PostgreSQL database, copying and adjusting the configuration file, initializing the database through the cross-platform linactl or compatible make entry, loading demo data, starting the development service, integrating AI Coding tools, and verifying that the installation is working correctly.","sidebar":"quickSidebar"},"quick/overview":{"id":"quick/overview","title":"Project Overview","description":"A comprehensive introduction to LinaPro \u2014 its background, architecture, and core capabilities. LinaPro is an AI-native full-stack framework built on Go + Vue 3 with PostgreSQL by default (optional SQLite), native multi-tenant support, an official plugin submodule, Redis cluster coordination, a dual-mode plugin system, RBAC permission management, scheduled task scheduling, live API documentation, the optional-but-recommended OpenSpec spec-driven AI development workflow, and a lifecycle-spanning AI skill set for building sustainable, continuously deliverable business systems.","sidebar":"quickSidebar"}}}}')}}]);